body {
    background-color: #f5f5f5;
    font-family: "Hiragino Kaku Gothic ProN", "Meiryo", sans-serif;
}

/* --- 共通レイアウト調整 --- */
.main-container {
    margin-top: 20px;
    margin-bottom: 50px;
}

.section-title {
    font-size: 1.1rem;
    font-weight: bold;
    border-bottom: 2px solid #ddd;
    padding-bottom: 10px;
    margin-bottom: 20px;
    color: #555;
}

/* --- 左側：グラフ・口コミ用スタイル --- */
.graph-wrapper {
    display: flex;
    flex-wrap: wrap;
    gap: 15px;
    justify-content: flex-start;
    margin-bottom: 30px;
}

.graph-card {
    background-color: #fff;
    padding: 15px;
    border-radius: 8px;
    box-shadow: 0 2px 5px rgba(0, 0, 0, 0.1);
    text-align: center;
    width: 260px;
}

.zemi-title {
    font-size: 1.1rem;
    font-weight: bold;
    margin-bottom: 5px;
    color: #333;
}

.zemi-tag {
    display: inline-block;
    background-color: #e2e6ea;
    color: #555;
    padding: 2px 8px;
    border-radius: 12px;
    font-size: 0.75rem;
    margin-bottom: 10px;
}

.graph-label {
    font-size: 10px;
    fill: #333;
    text-anchor: middle;
}

.review-group {
    background-color: #fff;
    padding: 15px;
    margin-bottom: 15px;
    border-radius: 8px;
    box-shadow: 0 2px 5px rgba(0, 0, 0, 0.1);
}

.review-item {
    background-color: #f9f9f9;
    padding: 8px 12px;
    margin-bottom: 5px;
    border-radius: 4px;
    border-left: 4px solid #3498db;
    font-size: 13px;
}

/* --- 右側：リスト用スタイル --- */
.lab-list-container {
    max-height: 80vh;
    overflow-y: auto;
    padding-right: 5px;
}

/* リストが長い場合にスクロール */
.lab-list-item {
    transition: background-color 0.2s;
    cursor: default;
}

.lab-list-item:hover {
    background-color: #f1f1f1;
}

.badge-score {
    font-size: 0.9rem;
}

/* --- ローディング --- */
.loading-spinner {
    display: block;
    margin: 30px auto;
}

/* Botpressのチャットウィンドウを最前面に表示する */
.bp-widget-widget {
    z-index: 2147 !important;
    /* 考えうる最大値を指定 */
}

// 検索条件の更新
let prevTag = '';
let prevSortKey = '';
let prevLabName = '';

async function refresh() {
    const res = await fetch('../latest');
    const parsed = await res.json();
    const data = typeof parsed.data === "string"
        ? JSON.parse(parsed.data)
        : parsed.data;
    if (!data) return;

    const tag = data.tag ?? '';
    const sortKey = data.sortKey ?? '';
    const labName = data.labName ?? '';
    if (tag && tag !== prevTag) {
        prevTag = tag;
        prevSortKey = '';
        prevLabName = '';

        updateView(tag, sortKey, labName);
    } else if (sortKey && sortKey !== prevSortKey) {
        prevTag = '';
        prevSortKey = sortKey;
        prevLabName = '';

        updateView(tag, sortKey, labName);
    } else if (labName && labName !== prevLabName) {
        prevTag = '';
        prevSortKey = '';
        prevLabName = labName;

        updateView(tag, sortKey, labName);
    }
}
setInterval(refresh, 1000);

const GAS_API_URL = "https://script.google.com/macros/s/AKfycbwJwBUDuIgYN4WNUlmmi5C53OSkBwob_iv9LFwVQ1tWV3Y2XUBO-OFIjuYdXFqWtVi8WA/exec";

async function updateView(tag = "", sortKey = "合計", labName = "") {
    // 要素を取得する
    const graphArea = document.getElementById("graphContainer");
    const commentArea = document.getElementById("commentContainer");
    const listArea = document.getElementById("lab-list");

    // 描画するビューの種類を判定する
    const viewType = (tag != "" || sortKey != "") ? "list" : (labName != "") ? "detail" : "none";
    if (viewType === "detail") {
        // 使わないページはローディング
        listArea.innerHTML = '<p class="text-center text-muted mt-3">読み込み中...</p>';
    } else if (viewType === "list") {
        // 使わないページはローディング
        graphArea.innerHTML = '<p class="text-center text-muted mt-3">読み込み中...</p>';
        commentArea.innerHTML = '<p class="text-center text-muted mt-3">読み込み中...</p>';
    }

    // 表示、非表示の切り替えを行う
    document.getElementById("view-list").style.display = (viewType === "list") ? "" : "none";
    document.getElementById("view-detail").style.display = (viewType === "detail") ? "" : "none";

    // データ取得後更新
    try {
        // GASにPOST
        const response = await fetch(GAS_API_URL, {
            method: "POST",
            body: JSON.stringify({ "labName": labName, "tag": tag, "sortKey": sortKey })
        });

        if (!response.ok) throw new Error("Network response was not ok");
        const data = await response.json();

        // データが空の場合
        if (data.length === 0 || 'error' in data) {
            const msg = '<p class="text-muted text-center w-100">該当する研究室はありませんでした。</p>';
            if (viewType === "detail") {
                graphArea.innerHTML = msg;
                commentArea.innerHTML = "";
            } else if (viewType === "list") {
                listArea.innerHTML = msg;
            }
            return;
        }

        // それぞれビューを更新
        if (viewType === "detail") {
            renderGraphs(data);
            renderComments(data);
        } else if (viewType === "list") {
            renderLabLists(data);
        }
    } catch (error) {
        console.error("Fetch error:", error);
        const errMsg = '<p class="text-danger text-center w-100">データ取得失敗</p>';
        if (viewType === "detail") {
            graphArea.innerHTML = errMsg;
            commentArea.innerHTML = "";
        } else if (viewType === "list") {
            listArea.innerHTML = errMsg;
        }
    }
}

// グラフ描画
function renderGraphs(data) {
    // グラフ描画用設定
    const graphKeys = ["作業量", "就活支援度", "研究支援度", "雰囲気", "成長性"];
    const size = 220, center = size / 2, radius = 70, maxValue = 5;

    // 座標を求める関数
    function getPoint(angle, value) {
        const r = (value / maxValue) * radius;
        return { x: center + r * Math.cos(angle), y: center + r * Math.sin(angle) };
    }

    // グラフ描画コンテナ
    const container = document.getElementById("graphContainer");
    container.innerHTML = '';

    // データ注入
    data.forEach(item => {
        const cardDiv = document.createElement("div");
        cardDiv.className = "graph-card";

        let svg = `<svg width="${size}" height="${size}" style="margin: 0 auto; display: block;">`;

        // グリッド
        for (let level = 1; level <= 5; level++) {
            const points = graphKeys.map((_, i) => {
                const angle = (Math.PI * 2 / 5) * i - Math.PI / 2;
                const p = getPoint(angle, level);
                return `${p.x},${p.y}`;
            }).join(" ");
            svg += `<polygon points="${points}" fill="none" stroke="#eee" stroke-width="1" />`;
        }

        // 軸
        graphKeys.forEach((key, i) => {
            const angle = (Math.PI * 2 / 5) * i - Math.PI / 2;
            const end = getPoint(angle, 5);
            const labelPos = getPoint(angle, 6.2);
            svg += `<line x1="${center}" y1="${center}" x2="${end.x}" y2="${end.y}" stroke="#ddd" />`;
            svg += `<text x="${labelPos.x}" y="${labelPos.y}" class="graph-label" dy="0.3em">${key}</text>`;
        });

        // データ
        const dataPoints = graphKeys.map((key, i) => {
            const angle = (Math.PI * 2 / 5) * i - Math.PI / 2;
            const val = item.metrics[key] || 0;
            const p = getPoint(angle, val);
            return `${p.x},${p.y}`;
        }).join(" ");
        svg += `<polygon points="${dataPoints}" fill="rgba(52,152,219,0.3)" stroke="#3498db" stroke-width="2" />`;
        svg += `</svg>`;

        cardDiv.innerHTML = `<div class="zemi-title">${item.zemiName}</div><div class="zemi-tag">#${item.tag}</div>` + svg;
        container.appendChild(cardDiv);
    });
}

// 口コミ詳細描画
function renderComments(data) {
    // 口コミコンテナ取得
    const container = document.getElementById("commentContainer");
    container.innerHTML = '';

    // データ注入
    data.forEach(item => {
        const groupDiv = document.createElement("div");
        groupDiv.className = "review-group";

        const reviewsHtml = (item.reviews && item.reviews.length > 0)
            ? item.reviews.map(r => `<div class="review-item">${r}</div>`).join('')
            : '<div class="text-muted small">口コミなし</div>';

        groupDiv.innerHTML = `
                    <div class="d-flex justify-content-between border-bottom pb-2 mb-2">
                        <strong>${item.zemiName}</strong>
                        <span class="badge badge-info">合計: ${item.metrics.合計}</span>
                    </div>
                    <div>${reviewsHtml}</div>
                `;
        container.appendChild(groupDiv);
    });
}

// リスト描画
function renderLabLists(data) {
    // 研究室一覧コンテナ取得
    const container = document.getElementById("lab-list");
    container.innerHTML = '';

    // データ注入
    data.forEach(lab => {
        const item = document.createElement("a");
        item.href = "#"; // クリックしても遷移しない
        item.className = "list-group-item list-group-item-action lab-list-item";
        item.innerHTML = `
                    <div class="d-flex w-100 justify-content-between align-items-center">
                        <h6 class="mb-1 text-dark font-weight-bold">${lab.zemiName}</h6>
                        <span class="badge badge-primary badge-score">${lab.metrics.合計}</span>
                    </div>
                    <div class="mb-1">
                        <span class="badge badge-light border">#${lab.tag}</span>
                    </div>
                    <small class="text-muted">就活: ${lab.metrics.就活支援度} / 雰囲気: ${lab.metrics.雰囲気}</small>
                `;
        container.appendChild(item);
    });
}

const syncplay = (audio) =>
    new Promise((res, rej) => {
        audio.onended = () => res();
        audio.onerror = (e) => rej(e);

        // play() が即 resolve/reject することがあるので、ハンドラを先に付ける
        const p = audio.play();
        if (p && typeof p.catch === "function") p.catch(rej);
    });

const playAudio = async (text) => {
    const url =
        "https://kdix-media-project-sfkbku37lq-an.a.run.app/tts/convert?gender=1&input_type=1&text=" +
        encodeURIComponent(String(text).replace(/<br>/g, "\n"));

    const res = await fetch(url, { cache: "force-cache" });
    if (!res.ok) throw new Error(`TTS fetch failed: ${res.status}`);

    const blob = await res.blob();
    const blobUrl = URL.createObjectURL(blob);

    try {
        await syncplay(new Audio(blobUrl));
    } finally {
        URL.revokeObjectURL(blobUrl);
    }
};

class QueueProcessor {
    constructor() {
        this.queue = [];
        this.isProcessing = false;
    }
    enqueue(item) {
        this.queue.push(item);
        if (!this.isProcessing) this.processQueue();
    }
    async processQueue() {
        this.isProcessing = true;
        while (this.queue.length > 0) {
            const t = this.queue.shift();
            try {
                await playAudio(t);
            } catch (e) {
                // 失敗してもキュー全体が止まらんように
                console.warn("TTS error:", e);
            }
        }
        this.isProcessing = false;
    }
}

const processor = new QueueProcessor();

// 連続重複・空文を軽く弾く（Botpressのイベント多重対策）
let lastText = "";
let lastAt = 0;

$(window).on("message", (event) => {
    const d = event.originalEvent ? event.originalEvent.data : event.data;
    const text = d?.payload?.text;

    if (!text) return;
    const t = String(text).trim();
    if (!t) return;

    const now = Date.now();
    if (t === lastText && now - lastAt < 500) return;
    lastText = t;
    lastAt = now;

    processor.enqueue(t);
});

