// 音声認識（無音検知付きの堅牢なバージョンを採用）
var onConversation = false;
var mediaRecorder = null;
var audioContext = null;
var chunks = [];
var terminate = false;
var restart_mediarecorder = false;
var do_not_repeat_detectsound = false;

// ===== UI helpers（追加）=====
const setStatus = (msg) => {
    const el = document.getElementById('stt_status');
    if (el) el.textContent = msg;
};

const setVU = (percent) => {
    const el = document.getElementById('vu');
    if (el) el.style.width = `${Math.max(0, Math.min(100, percent))}%`;
};

// メータ用の平滑化（見た目をなめらかにするだけ。処理は変えない）
let vuSmoothed = 0;
const smoothVU = (x) => (vuSmoothed = vuSmoothed * 0.8 + x * 0.2);

// 状態：IDLE / LISTENING / RECORDING / SENDING
setStatus('IDLE');
setVU(0);
// ============================

$('#stt_btn').click(function (e) {
    e.preventDefault();
    if (!onConversation) {
        $(this).addClass('btn-danger').removeClass('btn-primary').text('停止中...');
        setStatus('🎧 LISTENING...');
        startConversation();
        onConversation = true;
    } else {
        $(this).removeClass('btn-danger').addClass('btn-primary').text('音声認識開始');
        setStatus('IDLE');
        setVU(0);
        terminateConversation();
        onConversation = false;
    }
});

const onMediaRecorderStop = () => {
    if (terminate) { terminate = false; return; }
    if (restart_mediarecorder) {
        chunks = []; restart_mediarecorder = false; mediaRecorder.start(); return;
    }

    const blob = new Blob(chunks, { 'type': 'audio/webm' });
    chunks = [];

    // UIを一時的に青に戻す（自動再開しない場合）
    if (!onConversation) {
        $('#stt_btn').removeClass('btn-danger').addClass('btn-primary').text('音声認識開始');
        setStatus('IDLE');
        setVU(0);
    }

    setStatus('⏳ SENDING...');

    var fd = new FormData();
    fd.append('speech', blob, 'recorded.webm');
    fd.append('engine', "2");
    fd.append('mimetype', "2");

    $.ajax({
        url: 'https://kdix-media-project-sfkbku37lq-an.a.run.app/stt',
        type: "POST", data: fd, processData: false, contentType: false, dataType: 'json'
    }).done((response) => {
        if (response.text) {
            console.log("Detected: " + response.text);
            setStatus('✅ ' + response.text);
            window.botpressWebChat.sendPayload({ type: "text", text: response.text });
        } else {
            setStatus('…聞き取れんかった');
        }
    }).fail(() => {
        setStatus('⚠ STT失敗');
    }).always(() => {
        if (onConversation) setStatus('🎧 LISTENING...');
    });
};

const startConversation = () => {
    navigator.mediaDevices.getUserMedia({ video: false, audio: true }).then((stream) => {
        mediaRecorder = new MediaRecorder(stream);
        mediaRecorder.ondataavailable = (e) => chunks.push(e.data);
        mediaRecorder.onstop = onMediaRecorderStop;
        mediaRecorder.start();

        audioContext = new AudioContext();
        // ★追加：Chrome対策（suspendedのままを防ぐ）
        audioContext.resume?.();

        const source = audioContext.createMediaStreamSource(stream);
        const analyser = audioContext.createAnalyser();
        analyser.minDecibels = -45;
        analyser.fftSize = 2048; // ★追加：time-domainメータ用に明示
        source.connect(analyser);

        // 無音判定用（元のまま）
        const data = new Uint8Array(analyser.frequencyBinCount);
        // ★追加：メータ用（time-domain）
        const td = new Uint8Array(analyser.fftSize);

        let silenceSumThreshold = 100;
        let waitInterval = 100;
        var soundDetected = false;
        var silenceCount = 0;

        const detectSound = () => {
            // 無音判定（元のまま）
            analyser.getByteFrequencyData(data);
            var decsum = data.reduce((a, b) => a + b, 0);

            // ===== 音量メータ（表示だけ：確実に動くRMS方式）=====
            analyser.getByteTimeDomainData(td);
            let sum = 0;
            for (let i = 0; i < td.length; i++) {
                const v = (td[i] - 128) / 128;
                sum += v * v;
            }
            const rms = Math.sqrt(sum / td.length); // 0〜1くらい
            const vu = smoothVU(Math.min(100, Math.round((rms / 0.12) * 100))); // 0.12は目安
            setVU(vu);
            // ===================================================

            if (decsum <= silenceSumThreshold) {
                silenceCount++;
            } else {
                if (!soundDetected) setStatus('🟥 RECORDING...');
                soundDetected = true;
                silenceCount = 0;
            }

            if (soundDetected && silenceCount > waitInterval) {
                mediaRecorder.stop();
                soundDetected = false;
                silenceCount = 0;

                setStatus('🎧 LISTENING...');
                mediaRecorder.start();
            } else if (silenceCount > waitInterval) {
                silenceCount = 0;
                restart_mediarecorder = true;
                mediaRecorder.stop();
            }

            if (!do_not_repeat_detectsound) window.requestAnimationFrame(detectSound);
            else do_not_repeat_detectsound = false;
        };

        window.requestAnimationFrame(detectSound);
    });
}

const terminateConversation = () => {
    terminate = true;
    do_not_repeat_detectsound = true;
    if (audioContext) audioContext.close();
    if (mediaRecorder) mediaRecorder.stop();
}
